PRESETS += [dict(id='pdx88',name='PDX Carpet · Original Era',era='1980s / Portland',group='By Decade',description='Teal carpet with runway-like dark lines and red, blue and purple accents; a seamless nod to the original PDX carpet.',pattern='pdx',color='#399b8d',ink='#282e62',scale=120,intensity=60)]
DEFAULT = dict(pattern='paper',color='#eee9df',ink='#705d81',scale=100,intensity=20)
TABLES = {'publication':('zine_publication_appearance','zines'), 'issue':('zine_issue_appearance','zine_issues')}

def initialize(db):
    for table,parent in TABLES.values():
        db.execute(f'CREATE TABLE IF NOT EXISTS {table}(id TEXT PRIMARY KEY REFERENCES {parent}(id) ON DELETE CASCADE,settings TEXT NOT NULL CHECK(length(settings)<=768))')

def parse(form):
    out={k:form.get('backdrop_'+k, str(v)) for k,v in DEFAULT.items()}
    if out['pattern'] not in dict(PATTERNS):raise ZineError('Choose a supported backdrop.')
    for k in ('color','ink'):
        if not isinstance(out[k],str) or not re.fullmatch(r'#[0-9a-fA-F]{6}',out[k]):raise ZineError('Choose a six-digit backdrop color.')
        out[k]=out[k].lower()
    for k,low,high in [('scale',50,200),('intensity',0,60)]:
        try:v=int(out[k])
        except (ValueError,TypeError):raise ZineError('Choose a valid backdrop '+k+'.')
        if not low<=v<=high:raise ZineError('Backdrop '+k+' is outside its supported range.')
        out[k]=v
    return out

def get(db,scope,id):
    row=db.execute('SELECT settings FROM '+TABLES[scope][0]+' WHERE id=?',(id,)).fetchone()
    return json.loads(row['settings']) if row else None

def save(db,scope,id,form):
    mode=form.get('backdrop_mode','override')
    if mode not in ('inherit','override'):raise ZineError('Choose whether to inherit the publication backdrop.')
    table=TABLES[scope][0]
    if scope=='issue' and mode=='inherit':
        db.execute('DELETE FROM '+table+' WHERE id=?',(id,));return
    value=parse(form)
    db.execute('INSERT INTO '+table+'(id,settings) VALUES (?,?) ON CONFLICT(id) DO UPDATE SET settings=excluded.settings',(id,json.dumps(value)))

def context(db,zid=None,iid=None):
    publication=get(db,'publication',zid) if zid else None
    issue=get(db,'issue',iid) if iid else None
    effective=issue or publication or DEFAULT
    return dict(backdrop=effective,publication_backdrop=publication or DEFAULT,backdrop_dark=sum((v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4)*w for v,w in [(int(effective['color'][i:i+2],16)/255,w) for i,w in [(1,.2126),(3,.7152),(5,.0722)]])<.179,backdrop_override=issue is not None,backdrop_patterns=PATTERNS,backdrop_presets=[dict(p,css=css(p)) for p in PRESETS])

def css(value):
    # Every interpolated value comes from the same strict parser, including saved data.
    v=parse({'backdrop_'+k:x for k,x in value.items()})
    return f"--zine-ground:{v['color']};--zine-pattern-ink:{v['ink']};--zine-pattern-step:{16*v['scale']/100:g}px;--zine-pattern-opacity:{v['intensity']/100:g}"
